import torch
import torch.nn as nn

from .blocks import Bridge, TextBackbone, VisionEncoder
from .config import OmniConfig, get_config
from .heads import VAEDecoder, VAEEncoder, GenHead, GroundHead

TASK_VISION = 0
TASK_GROUND = 1
TASK_TEXT = 2
TASK_ASSIST = 3
TASK_GEN = 4


class OmniModel(nn.Module):
    """One model for every sector. Roles are conditioning, not modules:
    `role` indexes a learned embedding, so adding a persona costs 768 floats."""

    def __init__(self, cfg: OmniConfig):
        super().__init__()
        self.cfg = cfg
        self.vision = VisionEncoder(cfg)
        self.bridge = Bridge(cfg)
        self.text = TextBackbone(cfg)
        self.ground = GroundHead(cfg)
        if cfg.has_gen:
            self.gen = GenHead(cfg)
            self.vae_dec = VAEDecoder()
        else:
            self.gen = None
            self.vae_dec = None
        self.vae_enc = VAEEncoder()

    def encode_image(self, pix: torch.Tensor) -> torch.Tensor:
        return self.vision(pix)

    def prefill(self, pix, ids, role):
        v = self.vision(pix)
        return torch.cat([self.bridge(v), self.text.emb(ids) + self.text.roles(role)[:, None]], dim=1)

    def forward(self, pix, ids, role):
        v = self.vision(pix)
        vtok = self.bridge(v)
        b = ids.shape[0]
        ttok = self.text.emb(ids) + self.text.roles(role)[:, None]
        stream = torch.cat([vtok, ttok], dim=1)
        pos = self.text.pos[:, : stream.shape[1]]
        stream = stream + pos
        for blk in self.text.blocks:
            stream = blk(stream)
        logits = self.text.head(self.text.norm(stream[:, vtok.shape[1] :]))
        boxes, masks = self.ground(v)
        return logits, boxes, masks

    def gen_step(self, noise, cond, step):
        return self.gen(noise, cond, step)

    def decode_latent(self, z):
        return self.vae_dec(z)

    def encode_latent(self, img):
        return self.vae_enc(img)


def build(name: str = "omni-t", **kw) -> OmniModel:
    return OmniModel(get_config(name, **kw))

