// Does the classic TFLite C++ Interpreter keep a closed sector out of RAM?
//
// What we know so far, all measured on a 138 MB two-subgraph artifact:
//
//   ONNX Runtime                        +1305..1551 MB   file-resident 0.0
//   tf.lite.Interpreter(model_path=)    +141 MB          file-resident 0.0
//   LiteRT CompiledModel.from_file      +286 MB          file-resident 0.0
//
// Reading the 2.20 source explains the last two and changes the design.
// tensorflow/compiler/mlir/lite/core/model_builder_base.cc does this:
//
//   if (MMAPAllocation::IsSupported())
//     allocation = std::make_unique<MMAPAllocation>(filename, error_reporter);
//   else
//     allocation = std::make_unique<FileCopyAllocation>(filename, ...);
//
// So BuildFromFile already maps; there is no manual opt-in to discover. The
// Python Interpreter log line "Created TensorFlow Lite XNNPACK delegate for
// CPU" is the real culprit: a delegate repacks weights into its own anon
// buffers, which throws the mapping away. This probe is therefore built with
// TFLITE_ENABLE_XNNPACK=OFF, and the comparison it prints is the whole design
// decision: keep XNNPACK for speed and lose the mapping, or drop it and have
// sectors that cost nothing until opened.
#include <fcntl.h>
#include <sys/stat.h>
#include <unistd.h>

#include <cstdio>
#include <fstream>
#include <memory>
#include <string>

#include "tensorflow/lite/interpreter.h"
#include "tensorflow/lite/kernels/register.h"
#include "tensorflow/lite/model_builder.h"
#include "tensorflow/lite/stderr_reporter.h"

namespace {

std::string FileResidentMb(const std::string& path) {
  char resolved[4096];
  const char* real = realpath(path.c_str(), resolved) ? resolved : path.c_str();
  std::ifstream in("/proc/self/smaps");
  std::string line, owner;
  double kb = 0;
  while (std::getline(in, line)) {
    auto sp = line.find(' ');
    if (sp != std::string::npos && line.find('-') < sp && line.find(':') > sp) {
      auto rest = line.rfind(' ');
      owner = (rest != std::string::npos && rest > sp) ? line.substr(rest + 1) : "";
    } else if (line.rfind("Rss:", 0) == 0 && owner == real) {
      kb += atof(line.c_str() + 4);
    }
  }
  char buf[32];
  snprintf(buf, sizeof(buf), "%.1f", kb / 1024.0);
  return buf;
}

double RssMb() {
  std::ifstream in("/proc/self/status");
  std::string line;
  while (std::getline(in, line)) {
    if (line.rfind("VmRSS:", 0) == 0) return atof(line.c_str() + 6) / 1024.0;
  }
  return 0;
}

}  // namespace

int main(int argc, char** argv) {
  if (argc < 2) {
    fprintf(stderr, "usage: %s model.tflite [subgraph_index ...]\n", argv[0]);
    return 2;
  }
  const std::string path = argv[1];
  printf("MMAPAllocation::IsSupported() = %s\n",
         tflite::MMAPAllocation::IsSupported() ? "true" : "false");

  const double r0 = RssMb();
  auto model = tflite::FlatBufferModel::BuildFromFile(
      path.c_str(), tflite::DefaultErrorReporter());
  if (!model) {
    fprintf(stderr, "BuildFromFile failed\n");
    return 1;
  }
  tflite::ops::builtin::BuiltinOpResolver resolver;
  std::unique_ptr<tflite::Interpreter> interpreter;
  if (tflite::InterpreterBuilder(*model, resolver)(&interpreter) != kTfLiteOk) {
    fprintf(stderr, "InterpreterBuilder failed\n");
    return 1;
  }
  interpreter->SetNumThreads(2);

  int count = 0;
  while (interpreter->subgraph(count) != nullptr) ++count;
  auto keys = interpreter->signature_keys();
  printf("subgraphs: %d, signatures: %zu\n", count, keys.size());
  for (size_t i = 0; i < keys.size(); ++i) printf("  signature[%zu] = %s\n", i,
                                                   keys[i]->c_str());

  if (interpreter->AllocateTensors() != kTfLiteOk) {
    fprintf(stderr, "AllocateTensors failed\n");
    return 1;
  }
  double prev = RssMb();
  printf("\n%-22s %9s %14s %10s\n", "step", "RSS", "file-resident", "delta");
  printf("%-22s %9.1f %14s %10.1f\n", "load", prev, FileResidentMb(path).c_str(),
         prev - r0);

  for (int i = 2; i < argc; ++i) {
    const int idx = atoi(argv[i]);
    if (idx >= count) continue;
    if (interpreter->subgraph(idx)->Invoke() != kTfLiteOk) {
      fprintf(stderr, "subgraph %d invoke failed\n", idx);
      return 1;
    }
    const double r = RssMb();
    printf("%-22s %9.1f %14s %10.1f\n",
           ("run subgraph " + std::to_string(idx)).c_str(), r,
           FileResidentMb(path).c_str(), r - prev);
    prev = r;
  }
  return 0;
}

